+    private OpEffect executeConditionalAndOp(JavaOp.ConditionalAndOp o, Env e) {
+        for (Body body : o.bodies()) {
+            TerminatingOpEffect effect = executeBody(body, List.of(), e);
+            Optional<Boolean> b = processBooleanEffect(effect);
+            if (b.isEmpty()) {
